// === Tab: mySketch ===
let cloth=[];
let gravity;
let spacing = 30;
let cols, rows;
let stiffness = 0.18;
let damping = 0.95;  // Damping factor for particle velocity
let cutting = false;
let grabbedParticle = null;  // Variable to hold a grabbed particle
let counter=0

function setup() {
  createCanvas(windowWidth+20, windowHeight);
	background(0);
  cols = width / spacing;
  rows = height / spacing;
  gravity = createVector(0, 0.1);
  pixelDensity(.8)
	for(i=0;i<5;i++) cloth[i] = new Cloth(cols, rows);

}

function draw() {
spacing = random(50)
	background(0,.01)

	for(i=0;i<5;i++)
	{
		push()
			translate(0,-100,0)
			cloth[i].update();
			cloth[i].display();
		pop()


	if(counter%50==0)
	{
		cloth[i].cut(random(width), random(height));
	}
	}
}



// Cloth class
class Cloth {
  constructor(cols, rows) {
    this.particles = [];
    this.springs = [];

    // Create particles
    for (let i = 0; i < cols; i++) {
      this.particles[i] = [];
      for (let j = 0; j < rows; j++) {
        let fixed = (j == 0);
        this.particles[i][j] = new Particle(i * spacing, j * spacing, fixed);
      }
    }

    // Connecting particles with springs
    for (let i = 0; i < cols; i++) {
      for (let j = 0; j < rows; j++) {
        if (i > 0) {
          this.springs.push(new Spring(this.particles[i][j], this.particles[i - 1][j], stiffness));
        }
        if (j > 0) {
          this.springs.push(new Spring(this.particles[i][j], this.particles[i][j - 1], stiffness));
        }
      }
    }
  }

  update() {
    for (let spring of this.springs) {
      spring.update();
    }
    for (let row of this.particles) {
      for (let p of row) {
        p.applyForce(gravity);
        p.update();
      }
    }
  }

  display(type) {
    for (let spring of this.springs) {
      spring.display(type);
    }
  }

  grab(x, y) {
    for (let row of this.particles) {
      for (let p of row) {
        if (dist(x, y, p.pos.x, p.pos.y) < spacing / 2 && !p.fixed) {
          grabbedParticle = p; // Set the grabbed particle
          return;
        }
      }
    }
  }

  cut(x, y) {
    for (let i = this.springs.length - 1; i >= 0; i--) {
      let s = this.springs[i];
      let d1 = dist(x, y, s.p1.pos.x, s.p1.pos.y);
      let d2 = dist(x, y, s.p2.pos.x, s.p2.pos.y);
      if (d1 < spacing || d2 < spacing) {
        this.springs.splice(i, 1);
      }
    }
  }
}

// Particle class
class Particle {
  constructor(x, y, fixed) {
    this.pos = createVector(x, y);
    this.prevPos = this.pos.copy();
    this.fixed = fixed;
    this.vel = createVector(0, 0);
    this.acc = createVector(0, 0);
  }

  applyForce(force) {
    if (!this.fixed && this !== grabbedParticle) {
      this.acc.add(force);
    }
  }

  update() {
    if (!this.fixed) {
      if (this !== grabbedParticle) {
        this.vel.add(this.acc);
      }
      this.vel.mult(damping); // Apply damping
      this.pos.add(this.vel);
      this.acc.mult(0); // Clear acceleration
    }
  }
}

// Spring class
class Spring {
  constructor(p1, p2, stiffness) {
    this.p1 = p1;
    this.p2 = p2;
    this.length = p5.Vector.dist(p1.pos, p2.pos);
    this.stiffness = stiffness;
		this.r=random(255)
  }

  update() {
    let force = p5.Vector.sub(this.p2.pos, this.p1.pos);
    let x = force.mag() - this.length;
    force.normalize();
    force.mult(this.stiffness * x);
    this.p1.applyForce(force);
    force.mult(-1);
    this.p2.applyForce(force);
  }

  display(type) {
		if(type=="colored") stroke(random(255), random(255),random(255));
    else stroke(this.r, this.r,this.r);
    line(this.p1.pos.x, this.p1.pos.y, this.p2.pos.x, this.p2.pos.y);
  }
}

